<?php
function options(PDO $pdo,string $table,string $label='name',string $where="status='active'"): array { return $pdo->query("SELECT id,$label AS label FROM $table WHERE $where ORDER BY $label")->fetchAll(); }
function date_window(string $period): array { $today=date('Y-m-d'); return match($period){'yesterday'=>[date('Y-m-d',strtotime('-1 day')),date('Y-m-d',strtotime('-1 day'))],'7days'=>[date('Y-m-d',strtotime('-6 days')),$today],'30days'=>[date('Y-m-d',strtotime('-29 days')),$today],'month'=>[date('Y-m-01'),date('Y-m-t')],'lastmonth'=>[date('Y-m-01',strtotime('first day of last month')),date('Y-m-t',strtotime('last day of last month'))],'year'=>[date('Y-01-01'),date('Y-12-31')],default=>[$today,$today]}; }
function page_params(): array { $period=$_GET['period']??'today'; [$from,$to]=date_window($period); if($period==='custom'){ $from=$_GET['from']??$from;$to=$_GET['to']??$to;} $branch=(int)($_GET['branch']??0);if((int)(user()['branch_id']??0)&&(user()['role_slug']??'')!=='super-admin')$branch=(int)user()['branch_id'];return [$period,$from,$to,$branch,(int)($_GET['brand']??0)]; }
function page_title(string $title,string $eyebrow,string $description,string $button='',string $buttonHref=''): void { ?>
<div class="page-head"><div><span class="eyebrow"><?=e($eyebrow)?></span><h1><?=e($title)?></h1><p><?=e($description)?></p></div><?php if($button):?><a class="btn primary" href="<?=e($buttonHref)?>"><i data-icon="plus"></i><?=e($button)?></a><?php endif;?></div><?php }
function filter_bar(PDO $pdo,bool $dates=true): void { [$period,$from,$to,$branch,$brand]=page_params();$branches=options($pdo,'branches');$brands=options($pdo,'brands'); ?><form class="filters" method="get"><?php if($dates):?><select name="period" data-auto-submit><option value="today"<?=selected($period,'today')?>>Today</option><option value="yesterday"<?=selected($period,'yesterday')?>>Yesterday</option><option value="7days"<?=selected($period,'7days')?>>Last 7 Days</option><option value="30days"<?=selected($period,'30days')?>>Last 30 Days</option><option value="month"<?=selected($period,'month')?>>This Month</option><option value="lastmonth"<?=selected($period,'lastmonth')?>>Last Month</option><option value="year"<?=selected($period,'year')?>>This Year</option></select><?php endif;?><select name="branch" data-auto-submit><option value="0">All Branches</option><?php foreach($branches as $o):?><option value="<?=$o['id']?>"<?=selected($branch,$o['id'])?>><?=e($o['label'])?></option><?php endforeach;?></select><select name="brand" data-auto-submit><option value="0">All Brands</option><?php foreach($brands as $o):?><option value="<?=$o['id']?>"<?=selected($brand,$o['id'])?>><?=e($o['label'])?></option><?php endforeach;?></select></form><?php }
function pager(int $page,int $pages): void { if($pages<2)return;?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$i])))?>"><?=$i?></a><?php endfor;?></div><?php }
